import React, { ReactNode } from "react";
import { Dropdown } from "antd";
import { XftSubapplicationTopBar, type XftSubapplicationTopBarAction, type XftSubapplicationTopBarNavItem } from "./XftSubapplicationTopBar";
import "./XftTopBar.css";

const companyLogoAsset = "data:image/svg+xml;base64,";
const enterpriseIconAsset = "data:image/svg+xml;base64,";
const workbenchIconAsset = "data:image/svg+xml;base64,";
const allAppsIconAsset = "data:image/svg+xml;base64,";
const searchIconAsset = "data:image/svg+xml;base64,";
const supportIconAsset = "data:image/svg+xml;base64,";
const toolsArrowAsset = "data:image/svg+xml;base64,";
const dividerAsset = "data:image/svg+xml;base64,";
const avatarAsset = "data:image/png;base64,";
const accountArrowAsset = "data:image/svg+xml;base64,";

export type XftTopBarProps = {
  variant?: "global" | "smart-accounting" | "sub-application";
  brandName?: string;
  organizationName?: string;
  organizationLogo?: string;
  accountSetName?: string;
  accountingPeriod?: string;
  userName?: string;
  avatarUrl?: string;
  showPrimaryNav?: boolean;
  primaryNavItems?: XftSubapplicationTopBarNavItem[];
  activePrimaryNavKey?: string;
  utilityActions?: XftSubapplicationTopBarAction[];
  searchPlaceholder?: string;
  onSwitchOrganization?: () => void;
  onSwitchAccountSet?: () => void;
  onAccountingMonthAction?: (action: "previous" | "current" | "next") => void;
  onPrimaryNavChange?: (key: string) => void;
  onAllAppsClick?: () => void;
  onSearchChange?: (value: string) => void;
  onUtilityAction?: (key: string) => void;
  onGuideClick?: () => void;
  onNoticeClick?: () => void;
  onUserClick?: () => void;
  globalActions?: ReactNode;
};

const toolboxItems = [
  { key: "common-tools", label: "常用工具" },
  { key: "workflow-center", label: "流程中心" },
];

const userItems = [
  { key: "profile", label: "个人信息" },
  { key: "logout", label: "退出登录" },
];

export function XftTopBar({
  variant = "global",
  brandName = "应用名称",
  organizationName = "招商银行薪福通",
  organizationLogo = "招",
  accountSetName = "招银网络科技",
  accountingPeriod = "2024年6月",
  userName = "邱云",
  avatarUrl,
  showPrimaryNav = false,
  primaryNavItems,
  activePrimaryNavKey,
  utilityActions,
  searchPlaceholder,
  onSwitchOrganization,
  onSwitchAccountSet,
  onAccountingMonthAction,
  onPrimaryNavChange,
  onAllAppsClick,
  onSearchChange,
  onUtilityAction,
  onGuideClick,
  onNoticeClick,
  onUserClick,
  globalActions,
}: XftTopBarProps) {
  if (variant !== "global") return <XftSubapplicationTopBar
    variant={variant}
    brandName={brandName}
    organizationName={organizationName}
    accountSetName={accountSetName}
    accountingPeriod={accountingPeriod}
    userName={userName}
    avatarUrl={avatarUrl}
    showPrimaryNav={showPrimaryNav}
    primaryNavItems={primaryNavItems}
    activePrimaryNavKey={activePrimaryNavKey}
    utilityActions={utilityActions}
    searchPlaceholder={searchPlaceholder}
    onSwitchOrganization={onSwitchOrganization}
    onSwitchAccountSet={onSwitchAccountSet}
    onAccountingMonthAction={onAccountingMonthAction}
    onPrimaryNavChange={onPrimaryNavChange}
    onAllAppsClick={onAllAppsClick}
    onSearchChange={onSearchChange}
    onUtilityAction={onUtilityAction}
    onGuideClick={onGuideClick}
    onNoticeClick={onNoticeClick}
    onUserClick={onUserClick}
  />;

  const organizationLogoNode = organizationLogo === "招"
    ? <img className="xft-top-bar__logo" src={companyLogoAsset} alt="" aria-hidden="true" />
    : <span className="xft-top-bar__logo xft-top-bar__logo--text" aria-hidden="true">{organizationLogo}</span>;

  return <header className="xft-top-bar">
    <div className="xft-top-bar__left">
      <Dropdown menu={{ items: [{ key: "switch-organization", label: "切换企业" }] }} trigger={["click"]}>
        <button className="xft-top-bar__organization" type="button" aria-label="切换企业">
          {organizationLogoNode}
          <span className="xft-top-bar__organization-name">{organizationName}</span>
          <img className="xft-top-bar__enterprise-icon" src={enterpriseIconAsset} alt="" aria-hidden="true" />
        </button>
      </Dropdown>

      <button className="xft-top-bar__nav-item xft-top-bar__workbench" type="button">
        <img className="xft-top-bar__nav-icon" src={workbenchIconAsset} alt="" aria-hidden="true" />
        <span>工作台</span>
      </button>
      <button className="xft-top-bar__nav-item xft-top-bar__all-apps" type="button">
        <img className="xft-top-bar__nav-icon" src={allAppsIconAsset} alt="" aria-hidden="true" />
        <span>全部应用</span>
      </button>
    </div>

    <div className="xft-top-bar__right">
      {globalActions ? <div className="xft-top-bar__global-actions">{globalActions}</div> : null}
      <label className="xft-top-bar__search">
        <img className="xft-top-bar__search-icon" src={searchIconAsset} alt="" aria-hidden="true" />
        <input type="text" aria-label="输入关键词、问题" placeholder="输入关键词、问题" />
      </label>

      <div className="xft-top-bar__utility-group">
        <button className="xft-top-bar__icon-button" type="button" aria-label="客服">
          <img className="xft-top-bar__support-icon" src={supportIconAsset} alt="" aria-hidden="true" />
        </button>

        <Dropdown menu={{ items: toolboxItems }} trigger={["click"]}>
          <button className="xft-top-bar__utility-button" type="button">
            <span>工具箱</span>
            <img className="xft-top-bar__tools-arrow" src={toolsArrowAsset} alt="" aria-hidden="true" />
          </button>
        </Dropdown>

        <button className="xft-top-bar__utility-button xft-top-bar__management" type="button">管理后台</button>
        <img className="xft-top-bar__divider" src={dividerAsset} alt="" aria-hidden="true" />
      </div>

      <Dropdown menu={{ items: userItems }} trigger={["click"]}>
        <button className="xft-top-bar__user" type="button" aria-label={"用户 " + userName}>
          <img className="xft-top-bar__avatar" src={avatarAsset} alt="" aria-hidden="true" />
          <span className="xft-top-bar__user-name">
            <span>{userName}</span>
            <img className="xft-top-bar__account-arrow" src={accountArrowAsset} alt="" aria-hidden="true" />
          </span>
        </button>
      </Dropdown>
    </div>
  </header>;
}
